import { z } from 'zod'
import { MobileApiError } from './http'

/** Issued only by the positive-intent service; never generated by a retry. */
export const signupCompletionRequestKeySchema = z
  .string()
  .regex(/^osc1:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/)

export type SignupCompletionTransport =
  | { readonly mode: 'legacy'; readonly body: unknown }
  | {
      readonly mode: 'versioned'
      readonly intentId: string
      readonly requestKey: string
      readonly body: Record<string, unknown>
    }

/**
 * Pure provenance boundary, before even choosing completion versus partial update.
 * Availability is deliberately absent: switching ON must never promote a legacy
 * retry, and switching OFF must never demote an issued intent to a legacy write.
 * Existing generic legacy keys keep their validation in the existing handler.
 */
export function classifySignupCompletionTransport(
  body: unknown,
  requestKey: string | null,
): SignupCompletionTransport {
  const record =
    body !== null && typeof body === 'object' && !Array.isArray(body)
      ? (body as Record<string, unknown>)
      : undefined
  const hasProtocol = record !== undefined && Object.hasOwn(record, 'signup_strength_protocol')
  const hasIntent = record !== undefined && Object.hasOwn(record, 'completion_intent_id')
  // Reserve numeric protocol namespaces (including incomplete/case variants),
  // without taking unrelated old keys such as "oscillator-old-key".
  // Match the legacy schema's trim before deciding whether a key is reserved.
  // Otherwise NBSP/space prefixes could be normalized into an issued key only
  // after the caller had already selected the legacy writer.
  const reserved = requestKey !== null && /^osc(?:\d+(?::|$)|:|$)/i.test(requestKey.trim())
  if (!reserved && !hasProtocol && !hasIntent) return { mode: 'legacy', body }

  if (
    !record ||
    !hasProtocol ||
    !hasIntent ||
    !Object.hasOwn(record, 'document_actions') ||
    record.signup_strength_protocol !== 'osc1' ||
    !z.string().uuid().safeParse(record.completion_intent_id).success ||
    !signupCompletionRequestKeySchema.safeParse(requestKey).success
  )
    throw new MobileApiError(
      400,
      'invalid_signup_completion_transport',
      'Invalid signup completion transport',
    )

  const { signup_strength_protocol: _protocol, completion_intent_id: intentId, ...input } = record
  return Object.freeze({
    mode: 'versioned',
    intentId: intentId as string,
    requestKey: requestKey as string,
    body: input,
  })
}
